mermaid:
graph TD
    CLI["CLI Interface"]
    CP["Command Processor"]
    Parser["Parser Module"]
    Extractor["Annotation Extractor & Data Model Builder"]
    Generator["Generator Module"]
    Formatter["Formatter Module"]
    Config["Configuration & Overrides Loader"]
    FileIO["File I/O Module"]

    CLI -->|"invokes"| CP
    CP -->|"dispatches"| Parser
    Parser -->|"extracts"| Extractor
    Extractor -->|"builds"| Generator
    Generator -->|"writes"| FileIO

    CP -->|"triggersFmt"| Formatter
    Formatter -->|"formats"| FileIO

    FileIO -->|"readsSource"| Parser

    Config -->|"feeds"| Parser
    Config -->|"guides"| Generator

    classDef cli fill:#add8e6,stroke:#333,stroke-width:2px;
    classDef processor fill:#90ee90,stroke:#333,stroke-width:2px;
    classDef parser fill:#ffe4b5,stroke:#333,stroke-width:2px;
    classDef extractor fill:#ffb6c1,stroke:#333,stroke-width:2px;
    classDef generator fill:#d3d3d3,stroke:#333,stroke-width:2px;
    classDef formatter fill:#f5deb3,stroke:#333,stroke-width:2px;
    classDef config fill:#dda0dd,stroke:#333,stroke-width:2px;
    classDef fileio fill:#f0e68c,stroke:#333,stroke-width:2px;

    class CLI cli;
    class CP processor;
    class Parser parser;
    class Extractor extractor;
    class Generator generator;
    class Formatter formatter;
    class Config config;
    class FileIO fileio;

    click CLI "https://github.com/swaggo/swag/blob/master/cmd/swag/main.go"
    click CP "https://github.com/swaggo/swag/blob/master/cmd/swag/main.go"
    click Parser "https://github.com/swaggo/swag/blob/master/parser.go"
    click Extractor "https://github.com/swaggo/swag/blob/master/enums.go"
    click Extractor "https://github.com/swaggo/swag/blob/master/spec.go"
    click Generator "https://github.com/swaggo/swag/blob/master/gen/gen.go"
    click Formatter "https://github.com/swaggo/swag/blob/master/format/format.go"
    click Formatter "https://github.com/swaggo/swag/blob/master/formatter.go"
    click Config "https://github.com/swaggo/swag/blob/master/.goreleaser.yml"
    click Config "https://github.com/swaggo/swag/blob/master/example/override/.swaggo"
